let dekanproHeroSlider=function(e){let o=e.querySelector(".dekanpro-spinner"),t=function(){o.classList.remove("visible"),setTimeout((function(){o.style.display="none"}),300),e.classList.add("loaded")};return imagesLoaded(e,(function(){document.getElementById("dekanpro-preloader")&&!document.body.classList.contains("dekanpro-loaded")?document.body.addEventListener("dekanpro-preloader-done",(function(){setTimeout(t,300)})):setTimeout(t,300)})),e};document.addEventListener("DOMContentLoaded",(function(){document.querySelectorAll(".dekanpro-hero-slider").forEach((e=>{dekanproHeroSlider(e)}))}));